function isString(x: unknown): x is string {
  return typeof x === "string";
}

export async function buildCurated(ctx: BuildContext): Promise<CachedPin[]> {
  // De-duplicate titles across lists (first category wins).
  const seen = new Set<string>();
  const specs = SPECS.filter((s) => {
    if (seen.has(s.title)) return false;
    seen.add(s.title);
    return true;
  });
  return pinsFromTitles(ctx, specs, "wp");
}
